// Vérifie que la requête vient bien de Cloudinary.
//
// Ce webhook est une URL publique qui déclenche un commit sur le dépôt : sans
// cette vérification, n'importe qui connaissant l'adresse pourrait publier une
// image sur le site. Cloudinary signe chaque notification, on recalcule la
// signature et on refuse tout ce qui ne correspond pas.
//
// Formule Cloudinary : SHA1(corps_brut + timestamp + api_secret)
//
// On utilise l'API Web Crypto, disponible nativement dans Node : le module
// crypto de Node exigerait la variable d'environnement
// NODE_FUNCTION_ALLOW_BUILTIN, inutile ici.

const secret = $env.CLOUDINARY_API_SECRET;
if (!secret) {
  throw new Error(
    "Variable d'environnement CLOUDINARY_API_SECRET absente côté n8n."
  );
}

const entree = $('Webhook Cloudinary').first();
const headers = entree.json.headers || {};
const signatureRecue = headers['x-cld-signature'];
const timestamp = headers['x-cld-timestamp'];

if (!signatureRecue || !timestamp) {
  throw new Error('Requête non signée : en-têtes Cloudinary manquants.');
}

// Le corps doit être repris tel quel, octet pour octet. Ré-encoder l'objet JSON
// analysé produirait une chaîne différente et donc une signature invalide :
// c'est pourquoi l'option « Raw Body » est activée sur le nœud Webhook.
const corpsBrut =
  typeof entree.json.body === 'string'
    ? entree.json.body
    : Buffer.from(entree.binary.data.data, 'base64').toString('utf8');

const empreinte = await crypto.subtle.digest(
  'SHA-1',
  new TextEncoder().encode(corpsBrut + timestamp + secret)
);
const attendue = Array.from(new Uint8Array(empreinte))
  .map((o) => o.toString(16).padStart(2, '0'))
  .join('');

// Comparaison à durée constante : une comparaison classique s'arrête au premier
// caractère faux, ce qui laisse deviner la signature essai par essai.
const recue = String(signatureRecue);
let ecart = attendue.length ^ recue.length;
for (let i = 0; i < attendue.length; i++) {
  ecart |= attendue.charCodeAt(i) ^ recue.charCodeAt(i);
}
if (ecart !== 0) {
  throw new Error('Signature Cloudinary invalide : requête rejetée.');
}

// Rejette les notifications trop anciennes (rejeu d'une requête interceptée).
const ageSecondes = Math.floor(Date.now() / 1000) - Number(timestamp);
if (ageSecondes > 3600) {
  throw new Error(`Notification trop ancienne (${ageSecondes} s) : rejetée.`);
}

return [{ json: JSON.parse(corpsBrut) }];

// Insère la nouvelle photo dans photos.json.
//
// Le fichier reste la source unique de la galerie : on le lit, on y ajoute une
// entrée, on le réécrit. Aucune modification de HTML n'est nécessaire.

const config = $('Configuration').first().json;
const photo = $('Vérifier la signature Cloudinary').first().json;
const fichier = $('Lire photos.json').first().json;

// L'API GitHub renvoie le contenu encodé en base64.
const actuel = JSON.parse(
  Buffer.from(fichier.content, 'base64').toString('utf8')
);

// Cloudinary place les métadonnées saisies dans la médiathèque ici. Le texte
// alternatif décrit la photo pour les lecteurs d'écran et les moteurs de
// recherche : à renseigner dans Cloudinary, champ « alt ».
const contexte = (photo.context && photo.context.custom) || {};

// Couleur dominante, utilisée comme aplat pendant le chargement de la vignette.
// Présente seulement si l'analyse des couleurs est activée sur le preset
// d'upload ; sinon la galerie retombe sur un gris neutre.
let couleur = null;
if (Array.isArray(photo.colors) && photo.colors.length > 0) {
  couleur = photo.colors[0][0];
}

const nouvelle = {
  id: photo.public_id,
  version: String(photo.version),
  format: photo.format,
  width: photo.width,
  height: photo.height,
  alt: contexte.alt || contexte.caption || '',
};
if (couleur) {
  nouvelle.color = couleur;
}

// Cloudinary peut renvoyer plusieurs fois la même notification. Sans ce filtre,
// la photo apparaîtrait en double dans la galerie.
const dejaPresente = actuel.photos.some((p) => p.id === nouvelle.id);
if (dejaPresente) {
  return [
    {
      json: {
        ignore: true,
        raison: `Photo « ${nouvelle.id} » déjà présente dans photos.json.`,
      },
    },
  ];
}

// Les nouveautés en tête de galerie.
actuel.photos.unshift(nouvelle);

const contenu = JSON.stringify(actuel, null, 2) + '\n';

return [
  {
    json: {
      ignore: false,
      photo: nouvelle,
      total: actuel.photos.length,
      sha: fichier.sha,
      message: `Ajout de la photo ${nouvelle.id}`,
      contenuBase64: Buffer.from(contenu, 'utf8').toString('base64'),
      urlContenu: `https://api.github.com/repos/${config.proprietaire}/${config.depot}/contents/${config.chemin}`,
      branche: config.branche,
    },
  },
];
